#!/usr/bin/env python3
"""Measure the CONSUMPTION plane: how much of command-center is generated (projected)
vs hand-maintained, and how many objects the existing projection covers.

This is the evidence base for ux-product-first.md. Pure counting, no judgement.
Run: python platform/architecture/_uxpf_consumption.py
"""

from __future__ import annotations

import json
import subprocess
from pathlib import Path

REPO = Path("C:/Users/Prekzursil/source/ast-integrate")
CC = REPO / "command-center"
out: dict = {}

GEN_MARKERS = (
    "GENERATED by",
    "Do not hand-edit",
    "generated rather than maintained",
    "DO NOT EDIT",
)

# --- which command-center docs are generated vs hand-maintained? --------------
gen, hand = [], []
for p in sorted(CC.glob("*.md")):
    head = p.read_text(encoding="utf-8", errors="replace")[:600]
    (gen if any(m in head for m in GEN_MARKERS) else hand).append(p.name)
out["cc_md_generated"] = {"n": len(gen), "files": gen}
out["cc_md_hand_maintained"] = {"n": len(hand), "files": hand}

# scratch probe files (agent debris the owner must mentally filter)
out["cc_scratch_underscore_files"] = sum(
    1 for p in CC.iterdir() if p.is_file() and p.name.startswith("_")
)
out["cc_total_files_top_level"] = sum(1 for p in CC.iterdir() if p.is_file())

# --- coverage of the projection ----------------------------------------------
cat = json.loads((CC / "WORK-UNIT-CATALOG.json").read_text(encoding="utf-8"))
items, wus = cat.get("items", []), cat.get("work_units", [])
out["projected_objects_items"] = len(items)
out["unprojected_objects_work_units"] = len(wus)
out["projection_coverage_pct"] = round(100.0 * len(items) / (len(items) + len(wus)), 2)

# --- is the projection currently drift-free? (the mechanism must be proven) ---
r = subprocess.run(
    ["python", "tools/command-center/render.py", "--check"],
    cwd=REPO,
    capture_output=True,
    text=True,
)
out["render_check"] = {
    "exit": r.returncode,
    "stdout_tail": (r.stdout or "").strip()[-300:],
    "stderr_tail": (r.stderr or "").strip()[-300:],
}

# --- BOTH-STATES control: does --check FIRE on a known-broken state? ----------
# Mutate STATUS.md in memory-safe fashion: back up, corrupt, re-check, restore.
status = CC / "STATUS.md"
orig = status.read_bytes()
try:
    status.write_bytes(orig + b"\nDRIFT-INJECTED-BY-UXPF-PROBE\n")
    r2 = subprocess.run(
        ["python", "tools/command-center/render.py", "--check"],
        cwd=REPO,
        capture_output=True,
        text=True,
    )
    out["render_check_on_BROKEN_state"] = {
        "exit": r2.returncode,
        "stdout_tail": (r2.stdout or "").strip()[-300:],
    }
finally:
    status.write_bytes(orig)
r3 = subprocess.run(
    ["python", "tools/command-center/render.py", "--check"],
    cwd=REPO,
    capture_output=True,
    text=True,
)
out["render_check_after_restore"] = {"exit": r3.returncode}
out["DETECTOR_VALID_both_states"] = (
    out["render_check"]["exit"] == 0
    and out["render_check_on_BROKEN_state"]["exit"] != 0
    and r3.returncode == 0
)

# --- existing test coverage of the projection tooling ------------------------
t = subprocess.run(
    ["python", "-m", "pytest", "-q", "--no-header", "tools/command-center/tests"],
    cwd=REPO,
    capture_output=True,
    text=True,
)
out["projection_tests"] = {
    "exit": t.returncode,
    "tail": (t.stdout or t.stderr).strip()[-260:],
}

print(json.dumps(out, indent=2, ensure_ascii=False))
ok = out["DETECTOR_VALID_both_states"]
print(f"{'SUCCESS' if ok else 'FAILED'}:uxpf-consumption detector_valid={ok}")
